import * as T from './vendor/three.module.js';
import {adventures,startAdventure,advanceAdventure} from './expeditions.js';
import {makeNest} from './exploration.js';
import {makeDinosaur} from './dinosaurs.js';
import {species} from './island.js';
export function createExpeditions({state,inv,wardrobe,scene,ground,clearGround,blocked,save,resume,message,sound}){
 const $=id=>document.getElementById(id),group=new T.Group();scene.add(group);let current='',target=null;
 const ring=new T.Mesh(new T.TorusGeometry(.8,.1,6,24),new T.MeshBasicMaterial({color:0xffde72}));ring.rotation.x=Math.PI/2;group.add(ring);
 const marker=new T.Mesh(new T.OctahedronGeometry(.35),new T.MeshBasicMaterial({color:0xffeaa1}));group.add(marker);
 const tracks=new T.Group();group.add(tracks);for(let foot=0;foot<2;foot++)for(let toe=-1;toe<=1;toe++){const m=new T.Mesh(new T.BoxGeometry(.11,.035,.35),new T.MeshLambertMaterial({color:0x694e31}));m.position.set((foot-.5)*.55+toe*.12,.02,(foot-.5)*.4);m.rotation.y=toe*.4;tracks.add(m);}const nest=makeNest(0).g;group.add(nest);
 const chest=new T.Mesh(new T.BoxGeometry(1,.65,.7),new T.MeshLambertMaterial({color:0xc48b36}));group.add(chest);
 const baby=makeDinosaur(10,species[10].color).g;baby.scale.setScalar(.38);scene.add(baby);baby.visible=false;
 const family=makeDinosaur(10,species[10].color).g;scene.add(family);family.visible=false;
 // Choose a clear, dry patch without modifying a player's buildings.
 function place(step){let best=null,score=Infinity;for(let dx=-4;dx<=4;dx++)for(let dz=-4;dz<=4;dz++){const x=step.x+dx,z=step.z+dz,y=ground(x,z);if(y<.5||y>6||clearGround(x,z)>y+.3)continue;const slope=Math.max(...[[1,0],[-1,0],[0,1],[0,-1]].map(([a,b])=>Math.abs(ground(x+a,z+b)-y)));const n=dx*dx+dz*dz+slope*20;if(n<score){score=n;best={x,y,z};}}return best||{x:step.x,y:ground(step.x,step.z),z:step.z};}
 function sync(){const a=adventures.find(a=>a.id===state.active?.id);group.visible=!!a;$('expeditionHud').hidden=!a;if(!a){baby.visible=false;family.visible=false;target=null;current='';return;}const key=a.id+state.active.step;if(current===key)return;current=key;const step=a.steps[state.active.step];target=place(step);group.position.set(target.x,target.y+.15,target.z);tracks.visible=step.icon==='🐾';nest.visible=a.id==='egg'&&state.active.step===2;chest.visible=a.id==='treasure'&&state.active.step===3;chest.position.y=.35;baby.visible=a.id==='baby';family.visible=a.id==='baby'&&state.active.step===2;if(baby.visible){const previous=place(a.steps[Math.max(0,state.active.step-1)]);baby.position.set(previous.x,previous.y,previous.z);}if(family.visible)family.position.set(target.x+1,target.y,target.z);}
 function render(){sync();const list=$('expeditionList');list.replaceChildren();$('expeditionMedals').textContent='🏅 '+state.done.length+' / 3 médailles · '+(state.done.length===3?'Foulard d’explorateur offert ! Retrouve-le à la boutique.':'Trois médailles = un foulard d’explorateur pour tes dinos.');for(const a of adventures){const card=document.createElement('section');card.className='friend-card';const title=document.createElement('h3');title.textContent=a.icon+' '+a.name;const p=document.createElement('p');p.textContent=state.done.includes(a.id)?'🏅 Médaille gagnée':a.reward+' 💎 + une médaille · Sans chronomètre';const b=document.createElement('button');b.textContent=state.done.includes(a.id)?'Terminée ✓':state.active?.id===a.id?'Reprendre l’aventure':'Partir explorer';b.disabled=state.done.includes(a.id)||!!state.active&&state.active.id!==a.id;b.onclick=()=>{if(!state.active)startAdventure(state,a.id);sync();save();resume();message('🧭 Suis la flèche dorée. Approche du repère puis appuie sur ✋.');};card.append(title,p,b);list.append(card);}if(state.active){const b=document.createElement('button');b.textContent='Quitter cette aventure';b.onclick=()=>{state.active=null;sync();save();render();};list.append(b);}}
 function near(pos){return target&&Math.hypot(pos.x-target.x,pos.z-target.z)<3.5&&Math.abs(pos.y-target.y-1.65)<3&&!blocked(pos,new T.Vector3(target.x,target.y+.8,target.z));}
 function act(pos){sync();if(!near(pos))return false;const a=adventures.find(a=>a.id===state.active.id);if(a.id==='baby'&&state.active.step>0&&baby.position.distanceTo(new T.Vector3(target.x,target.y,target.z))>5){message('🦕 Attends ton petit compagnon !');return true;}const result=advanceAdventure(state,inv,wardrobe);sync();save();sound(result.complete?'treasure':'craft');message(result.complete?'🏅 Bravo ! +'+result.reward+' diamants'+(result.unlocked?' · Foulard d’explorateur débloqué !':''):a.id==='egg'&&state.active.step===3?'🥚 L’œuf est avec toi ! Rapporte-le au camp.':'✨ Bien joué ! Suis le prochain repère.');return true;}
 function update(dt,time,pos,yaw){sync();if(!target)return;marker.position.y=2.8+Math.sin(time*2)*.15;marker.rotation.y=time;const a=adventures.find(a=>a.id===state.active.id),step=a.steps[state.active.step];if(a.id==='baby'&&state.active.step>0){const dx=pos.x-baby.position.x,dz=pos.z-baby.position.z,d=Math.hypot(dx,dz);if(d>2){const k=Math.min(dt*3.5,d-2)/d,x=baby.position.x+dx*k,z=baby.position.z+dz*k,y=ground(x,z);if(y>=.5&&Math.abs(y-baby.position.y)<1.1&&!blocked(baby.position,new T.Vector3(x,y+.5,z)))baby.position.set(x,y,z);baby.rotation.y=Math.atan2(-dx,-dz);}}const angle=Math.atan2(target.x-pos.x,pos.z-target.z)+yaw;$('expeditionArrow').style.transform='rotate('+angle+'rad)';$('expeditionText').textContent=step.icon+' '+step.text+' · '+Math.round(Math.hypot(target.x-pos.x,target.z-pos.z))+' m';$('expeditionAct').hidden=!near(pos);$('expeditionAct').textContent=a.id==='treasure'&&state.active.step===3?'✋ Ouvrir le coffre':a.id==='baby'&&state.active.step===0?'✋ Viens avec moi':'✋ Continuer';}
 $('expeditionRecall').onclick=()=>{if(state.active?.id!=='baby'||state.active.step<1)return;recallRequested=true;};let recallRequested=false;const tick=update;function withRecall(dt,time,pos,yaw){tick(dt,time,pos,yaw);$('expeditionRecall').hidden=state.active?.id!=='baby'||state.active.step<1;if(recallRequested){recallRequested=false;const spot=place({x:Math.round(pos.x),z:Math.round(pos.z)});if(Math.hypot(spot.x-pos.x,spot.z-pos.z)<6){baby.position.set(spot.x,spot.y,spot.z);message('🦕 Le bébé te rejoint !');}else message('Rejoins la terre ferme pour appeler le bébé.');}}sync();return {render,update:withRecall,act};
}
